// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test for strncasecmp().
 */
#include <kunit/test.h>
#include <linux/string.h>

static void equal_ignoring_case(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("hello", "hello", 5));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("hello", "HELLO", 5));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("HeLLo", "hEllO", 5));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("Hello World 123", "hELLO wORLD 123", 15));
}

static void zero_length(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abc", "xyz", 0));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("", "xyz", 0));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abc", "", 0));
}

static void length_limits_comparison(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abcX", "ABCY", 3));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("abcX", "ABCY", 4));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("axyz", "AXYZ", 1));
	KUNIT_EXPECT_LT(test, strncasecmp("a", "b", 1), 0);
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abc", "ABC", 1000));
}

static void mismatch_at_each_position(struct kunit *test)
{
	KUNIT_EXPECT_GT(test, strncasecmp("xbc", "abc", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("axc", "abc", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abx", "abc", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abx", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "axc", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "xbc", 3), 0);
}

static void return_value_is_difference(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 1, strncasecmp("b", "a", 1));
	KUNIT_EXPECT_EQ(test, -1, strncasecmp("a", "b", 1));
	KUNIT_EXPECT_EQ(test, 1, strncasecmp("B", "a", 1));
	KUNIT_EXPECT_EQ(test, 1, strncasecmp("b", "A", 1));
	KUNIT_EXPECT_EQ(test, -1, strncasecmp("A", "b", 1));
	KUNIT_EXPECT_EQ(test, -1, strncasecmp("a", "B", 1));
	KUNIT_EXPECT_EQ(test, 'z' - 'a', strncasecmp("Z", "a", 1));
}

static void different_lengths(struct kunit *test)
{
	KUNIT_EXPECT_GT(test, strncasecmp("abcd", "abc", 4), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abcd", 4), 0);
	KUNIT_EXPECT_EQ(test, 'd', strncasecmp("abcd", "abc", 4));
	KUNIT_EXPECT_EQ(test, -'d', strncasecmp("ABC", "abcd", 4));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("abcd", "ABC", 3));
}

static void empty_strings(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("", "", 5));
	KUNIT_EXPECT_LT(test, strncasecmp("", "a", 5), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("a", "", 5), 0);
	KUNIT_EXPECT_EQ(test, 'a', strncasecmp("a", "", 1));
}

static void stops_at_nul(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("ab\0x", "AB\0y", 4));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("ab\0x", "AB\0y", 100));
}

static void non_letter_boundaries(struct kunit *test)
{
	/* neighbours of the A-Z and a-z ranges must not fold together */
	KUNIT_EXPECT_NE(test, 0, strncasecmp("@", "`", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("[", "{", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("@", "a", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("`", "A", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("[", "k", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("{", "K", 1));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("a", "A", 1));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("z", "Z", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("0", "1", 1));
	KUNIT_EXPECT_NE(test, 0, strncasecmp("_", "-", 1));
}

static void all_letters(struct kunit *test)
{
	char lo[2] = "a";
	char up[2] = "A";
	char c;

	for (c = 'a'; c <= 'z'; c++) {
		lo[0] = c;
		up[0] = c - 'a' + 'A';
		KUNIT_EXPECT_EQ(test, 0, strncasecmp(lo, up, 1));
		KUNIT_EXPECT_EQ(test, 0, strncasecmp(up, lo, 1));
	}
}

static void high_bit_unsigned(struct kunit *test)
{
	KUNIT_EXPECT_GT(test, strncasecmp("\xff", "a", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("a", "\xff", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("\x80", "\x7f", 1), 0);
	KUNIT_EXPECT_EQ(test, 0, strncasecmp("\xe9", "\xe9", 1));
}

static void same_pointer(struct kunit *test)
{
	const char *s = "SameString";

	KUNIT_EXPECT_EQ(test, 0, strncasecmp(s, s, 10));
	KUNIT_EXPECT_EQ(test, 0, strncasecmp(s, s, 100));
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(equal_ignoring_case),
	KUNIT_CASE(zero_length),
	KUNIT_CASE(length_limits_comparison),
	KUNIT_CASE(mismatch_at_each_position),
	KUNIT_CASE(return_value_is_difference),
	KUNIT_CASE(different_lengths),
	KUNIT_CASE(empty_strings),
	KUNIT_CASE(stops_at_nul),
	KUNIT_CASE(non_letter_boundaries),
	KUNIT_CASE(all_letters),
	KUNIT_CASE(high_bit_unsigned),
	KUNIT_CASE(same_pointer),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit test for strncasecmp");
MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */

#include <kunit/test.h>
#include <linux/string.h>

static void strcspn_empty_s(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("", ""), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("", "abc"), (size_t)0);
}

static void strcspn_empty_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", ""), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("a", ""), (size_t)1);
}

static void strcspn_no_match(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "xyz"), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "HELLO"), (size_t)5);
}

static void strcspn_match_first(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "h"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "xyzh"), (size_t)0);
}

static void strcspn_match_last(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "o"), (size_t)4);
	KUNIT_EXPECT_EQ(test, strcspn("a", "a"), (size_t)0);
}

static void strcspn_match_middle(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "l"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("hello world", " "), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("key=value", "=:"), (size_t)3);
}

static void strcspn_first_of_many(struct kunit *test)
{
	/* earliest position of any reject char wins, regardless of reject order */
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "fed"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "dfe"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "bcd"), (size_t)1);
}

static void strcspn_last_reject_char(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "xyzc"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "xyzf"), (size_t)5);
}

static void strcspn_duplicates(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("aaab", "bb"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("aaab", "aaaa"), (size_t)0);
}

static void strcspn_stops_at_nul(struct kunit *test)
{
	char buf[] = { 'a', 'b', '\0', 'c', 'd', '\0' };

	KUNIT_EXPECT_EQ(test, strcspn(buf, "c"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn(buf, "d"), (size_t)2);
}

static void strcspn_nul_not_matched(struct kunit *test)
{
	/* terminator of s is not part of the scan */
	KUNIT_EXPECT_EQ(test, strcspn("abc", "xyz"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("abc", ""), (size_t)3);
}

static void strcspn_case_sensitive(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("aBc", "b"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("aBc", "B"), (size_t)1);
}

static void strcspn_high_bit_chars(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("ab\x80\xff" "c", "\xff"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("ab\x80\xff" "c", "\x80"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("ab\x80\xff" "c", "\x7f"), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("a\x01" "b", "\x01"), (size_t)1);
}

static void strcspn_reject_longer_than_s(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("ab", "zyxwvutsrqb"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("ab", "zyxwvutsrq"), (size_t)2);
}

static void strcspn_long_string(struct kunit *test)
{
	char buf[1025];

	memset(buf, 'a', sizeof(buf) - 1);
	buf[sizeof(buf) - 1] = '\0';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), (size_t)1024);
	buf[1023] = 'b';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), (size_t)1023);
	buf[500] = 'b';
	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), (size_t)500);
}

static void strcspn_all_rejected(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "cba"), (size_t)0);
}

static void strcspn_suffix_pointer(struct kunit *test)
{
	const char *s = "ab,cd,ef";

	KUNIT_EXPECT_EQ(test, strcspn(s, ","), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn(s + 3, ","), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn(s + 6, ","), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn(s + 2, ","), (size_t)0);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(strcspn_empty_s),
	KUNIT_CASE(strcspn_empty_reject),
	KUNIT_CASE(strcspn_no_match),
	KUNIT_CASE(strcspn_match_first),
	KUNIT_CASE(strcspn_match_last),
	KUNIT_CASE(strcspn_match_middle),
	KUNIT_CASE(strcspn_first_of_many),
	KUNIT_CASE(strcspn_last_reject_char),
	KUNIT_CASE(strcspn_duplicates),
	KUNIT_CASE(strcspn_stops_at_nul),
	KUNIT_CASE(strcspn_nul_not_matched),
	KUNIT_CASE(strcspn_case_sensitive),
	KUNIT_CASE(strcspn_high_bit_chars),
	KUNIT_CASE(strcspn_reject_longer_than_s),
	KUNIT_CASE(strcspn_long_string),
	KUNIT_CASE(strcspn_all_rejected),
	KUNIT_CASE(strcspn_suffix_pointer),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit tests for strcspn");
MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/string_helpers.h>
#include <linux/string.h>
#include <linux/sizes.h>

static void check(struct kunit *test, u64 size, u64 blk,
		  enum string_size_units units, const char *want)
{
	char buf[32];
	int ret;

	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(size, blk, units, buf, sizeof(buf));
	KUNIT_EXPECT_STREQ_MSG(test, buf, want, "size=%llu blk=%llu units=%x",
			       size, blk, units);
	KUNIT_EXPECT_EQ(test, ret, (int)strlen(want));
}

static void zero_cases(struct kunit *test)
{
	check(test, 0, 1, STRING_UNITS_10, "0 B");
	check(test, 0, 1, STRING_UNITS_2, "0 B");
	check(test, 5, 0, STRING_UNITS_10, "0 B");
	check(test, 5, 0, STRING_UNITS_2, "0 B");
	check(test, 0, 0, STRING_UNITS_2, "0 B");
	check(test, 0, 512, STRING_UNITS_10 | STRING_UNITS_NO_SPACE, "0B");
}

static void base10_boundaries(struct kunit *test)
{
	check(test, 1, 1, STRING_UNITS_10, "1.00 B");
	check(test, 999, 1, STRING_UNITS_10, "999 B");
	check(test, 1000, 1, STRING_UNITS_10, "1.00 kB");
	check(test, 1001, 1, STRING_UNITS_10, "1.00 kB");
	check(test, 1004, 1, STRING_UNITS_10, "1.00 kB");
	check(test, 1005, 1, STRING_UNITS_10, "1.01 kB");
	check(test, 1500, 1, STRING_UNITS_10, "1.50 kB");
	check(test, 1999, 1, STRING_UNITS_10, "2.00 kB");
	check(test, 9990, 1, STRING_UNITS_10, "9.99 kB");
	check(test, 9995, 1, STRING_UNITS_10, "10.00 kB");
	check(test, 10000, 1, STRING_UNITS_10, "10.0 kB");
	check(test, 99900, 1, STRING_UNITS_10, "99.9 kB");
	check(test, 100000, 1, STRING_UNITS_10, "100 kB");
	check(test, 999000, 1, STRING_UNITS_10, "999 kB");
	check(test, 1000000, 1, STRING_UNITS_10, "1.00 MB");
	check(test, 1000000000ULL, 1, STRING_UNITS_10, "1.00 GB");
	check(test, 1000000000000ULL, 1, STRING_UNITS_10, "1.00 TB");
	check(test, 1000000000000000ULL, 1, STRING_UNITS_10, "1.00 PB");
	check(test, 1000000000000000000ULL, 1, STRING_UNITS_10, "1.00 EB");
}

static void base2_boundaries(struct kunit *test)
{
	check(test, 1, 1, STRING_UNITS_2, "1.00 B");
	check(test, 1023, 1, STRING_UNITS_2, "1023 B");
	check(test, 1024, 1, STRING_UNITS_2, "1.00 KiB");
	check(test, 1536, 1, STRING_UNITS_2, "1.50 KiB");
	check(test, 10240, 1, STRING_UNITS_2, "10.0 KiB");
	check(test, 102400, 1, STRING_UNITS_2, "100 KiB");
	check(test, SZ_1M, 1, STRING_UNITS_2, "1.00 MiB");
	check(test, SZ_1G, 1, STRING_UNITS_2, "1.00 GiB");
	check(test, SZ_1G * 4ULL, 1, STRING_UNITS_2, "4.00 GiB");
	check(test, 1ULL << 40, 1, STRING_UNITS_2, "1.00 TiB");
	check(test, 1ULL << 50, 1, STRING_UNITS_2, "1.00 PiB");
	check(test, 1ULL << 60, 1, STRING_UNITS_2, "1.00 EiB");
	check(test, 3ULL << 59, 1, STRING_UNITS_2, "1.50 EiB");
}

static void block_sizes(struct kunit *test)
{
	check(test, 2, 512, STRING_UNITS_10, "1.02 kB");
	check(test, 2, 512, STRING_UNITS_2, "1.00 KiB");
	check(test, 1, 4096, STRING_UNITS_2, "4.00 KiB");
	check(test, 1953525168ULL, 512, STRING_UNITS_10, "1.00 TB");
	check(test, 1953525168ULL, 512, STRING_UNITS_2, "932 GiB");
	check(test, 1, 1ULL << 40, STRING_UNITS_2, "1.00 TiB");
	check(test, 1ULL << 40, 1ULL << 20, STRING_UNITS_2, "1.00 EiB");
	check(test, 1ULL << 33, 1ULL << 33, STRING_UNITS_2, "64.0 EiB");
}

static void large_values(struct kunit *test)
{
	check(test, ~0ULL, 1, STRING_UNITS_2, "16.0 EiB");
	check(test, ~0ULL, 1, STRING_UNITS_10, "18.4 EB");
	check(test, 1ULL << 63, 1ULL << 63, STRING_UNITS_2, "64.0 UNKB");
	check(test, 1ULL << 63, 1ULL << 63, STRING_UNITS_10, "85.1 UNKB");
}

static void flags(struct kunit *test)
{
	check(test, 1500, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE, "1.50kB");
	check(test, 1500, 1, STRING_UNITS_10 | STRING_UNITS_NO_BYTES, "1.50 k");
	check(test, 1500, 1,
	      STRING_UNITS_10 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES,
	      "1.50k");
	check(test, 1536, 1, STRING_UNITS_2 | STRING_UNITS_NO_SPACE, "1.50KiB");
	check(test, 1536, 1, STRING_UNITS_2 | STRING_UNITS_NO_BYTES, "1.50 Ki");
	check(test, 5, 1, STRING_UNITS_10 | STRING_UNITS_NO_BYTES, "5.00 ");
	check(test, 5, 1,
	      STRING_UNITS_10 | STRING_UNITS_NO_BYTES | STRING_UNITS_NO_SPACE,
	      "5.00");
	check(test, 0, 1, STRING_UNITS_2 | STRING_UNITS_NO_BYTES, "0 ");
}

static void truncation(struct kunit *test)
{
	char buf[16];
	int ret;

	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1000, 1, STRING_UNITS_10, buf, 4);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "1.0");
	KUNIT_EXPECT_EQ(test, buf[4], 'X');

	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1000, 1, STRING_UNITS_10, buf, 7);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "1.00 k");

	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1000, 1, STRING_UNITS_10, buf, 8);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_STREQ(test, buf, "1.00 kB");

	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1000, 1, STRING_UNITS_10, buf, 1);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_EQ(test, buf[0], '\0');
	KUNIT_EXPECT_EQ(test, buf[1], 'X');

	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1000, 1, STRING_UNITS_10, buf, 0);
	KUNIT_EXPECT_EQ(test, ret, 7);
	KUNIT_EXPECT_EQ(test, buf[0], 'X');

	ret = string_get_size(0, 1, STRING_UNITS_10, buf, 3);
	KUNIT_EXPECT_EQ(test, ret, 3);
	KUNIT_EXPECT_STREQ(test, buf, "0 ");
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(zero_cases),
	KUNIT_CASE(base10_boundaries),
	KUNIT_CASE(base2_boundaries),
	KUNIT_CASE(block_sizes),
	KUNIT_CASE(large_values),
	KUNIT_CASE(flags),
	KUNIT_CASE(truncation),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

