// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */

#include <kunit/test.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define SENT 0x55

/* Escape with a roomy buffer and compare result and return value. */
static void check(struct kunit *test, const char *src, size_t isz,
		  unsigned int flags, const char *only, const char *exp)
{
	char buf[256];
	size_t elen = strlen(exp);
	int ret;

	memset(buf, SENT, sizeof(buf));
	ret = string_escape_mem(src, isz, buf, sizeof(buf), flags, only);
	KUNIT_EXPECT_EQ(test, ret, (int)elen);
	KUNIT_EXPECT_EQ(test, memcmp(buf, exp, elen), 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[elen], (unsigned char)SENT);
}

/* For every osz, ret is the full length and nothing past osz is written. */
static void check_trunc(struct kunit *test, const char *src, size_t isz,
			unsigned int flags, const char *only, const char *exp)
{
	size_t elen = strlen(exp), osz, i;
	char buf[64];
	int ret;

	for (osz = 0; osz <= elen + 2; osz++) {
		memset(buf, SENT, sizeof(buf));
		ret = string_escape_mem(src, isz, buf, osz, flags, only);
		KUNIT_ASSERT_EQ(test, ret, (int)elen);
		for (i = 0; i < sizeof(buf); i++) {
			if (i < osz && i < elen)
				KUNIT_ASSERT_EQ(test, buf[i], exp[i]);
			else
				KUNIT_ASSERT_EQ(test, (unsigned char)buf[i],
						(unsigned char)SENT);
		}
	}
}

static void test_space(struct kunit *test)
{
	check(test, "\n\r\t\v\f", 5, ESCAPE_SPACE, NULL, "\\n\\r\\t\\v\\f");
	check(test, "a\\\"\a\e", 5, ESCAPE_SPACE, NULL, "a\\\"\a\e");
	check(test, " ", 1, ESCAPE_SPACE, NULL, " ");
}

static void test_special(struct kunit *test)
{
	check(test, "\\\a\e\"", 4, ESCAPE_SPECIAL, NULL, "\\\\\\a\\e\\\"");
	check(test, "\n\tx", 3, ESCAPE_SPECIAL, NULL, "\n\tx");
}

static void test_null(struct kunit *test)
{
	check(test, "a\0b", 3, ESCAPE_NULL, NULL, "a\\0b");
	check(test, "\0\0", 2, ESCAPE_NULL, NULL, "\\0\\0");
	check(test, "\1\n", 2, ESCAPE_NULL, NULL, "\1\n");
}

static void test_octal(struct kunit *test)
{
	check(test, "\1\x7f\x80\xff\0", 5, ESCAPE_OCTAL, NULL,
	      "\\001\\177\\200\\377\\000");
	check(test, "a\n", 2, ESCAPE_OCTAL, NULL, "\\141\\012");
	check(test, "\x3f\x40\x07\x08", 4, ESCAPE_OCTAL, NULL,
	      "\\077\\100\\007\\010");
}

static void test_hex(struct kunit *test)
{
	check(test, "\1\x7f\x80\xff\0", 5, ESCAPE_HEX, NULL,
	      "\\x01\\x7f\\x80\\xff\\x00");
	check(test, "\x9a\xaf", 2, ESCAPE_HEX, NULL, "\\x9a\\xaf");
}

static void test_hex_and_octal(struct kunit *test)
{
	/* octal wins when both given */
	check(test, "\xff", 1, ESCAPE_OCTAL | ESCAPE_HEX, NULL, "\\377");
}

static void test_any(struct kunit *test)
{
	check(test, "a\n\\\0\x01", 5, ESCAPE_ANY, NULL,
	      "\\141\\n\\\\\\0\\001");
	check(test, "\n\\\0\x01", 4, ESCAPE_ANY, NULL, "\\n\\\\\\0\\001");
}

static void test_np(struct kunit *test)
{
	check(test, "ab c~", 5, ESCAPE_NP | ESCAPE_OCTAL, NULL, "ab c~");
	check(test, "a\n\x7f\1", 4, ESCAPE_NP | ESCAPE_OCTAL, NULL,
	      "a\\012\\177\\001");
	check(test, "a\n\x7f", 3, ESCAPE_ANY_NP, NULL, "a\\n\\177");
	/* printable chars pass through before the special class is consulted */
	check(test, "\"\\x", 3, ESCAPE_ANY_NP, NULL, "\"\\x");
	check(test, "\n", 1, ESCAPE_NP, NULL, "\n");
}

static void test_na(struct kunit *test)
{
	check(test, "a\n\x7f\x80\xff", 5, ESCAPE_NA | ESCAPE_OCTAL, NULL,
	      "a\n\x7f\\200\\377");
	check(test, "a\x80\x7f\x81", 4, ESCAPE_NA | ESCAPE_HEX, NULL,
	      "a\\x80\x7f\\x81");
}

static void test_nap(struct kunit *test)
{
	check(test, "a \x1f\x7f\x80", 5, ESCAPE_NAP | ESCAPE_OCTAL, NULL,
	      "a \\037\\177\\200");
	check(test, "a\n\x80", 3, ESCAPE_NAP | ESCAPE_SPACE | ESCAPE_HEX, NULL,
	      "a\\n\\x80");
	check(test, "~\x7f", 2, ESCAPE_NAP | ESCAPE_HEX, NULL, "~\\x7f");
}

static void test_only(struct kunit *test)
{
	/* only chars in @only are candidates for escaping */
	check(test, "a\nb\t", 4, ESCAPE_SPACE, "\n", "a\\nb\t");
	check(test, "a\nb\t", 4, ESCAPE_SPACE, "\t", "a\nb\\t");
	check(test, "abc", 3, ESCAPE_OCTAL, "b", "a\\142c");
	check(test, "abc", 3, ESCAPE_OCTAL, "", "\\141\\142\\143");
	check(test, "abc", 3, ESCAPE_OCTAL, "xyz", "abc");
}

static void test_append(struct kunit *test)
{
	/* APPEND: chars in @only escaped in addition to the NP/NA/NAP class */
	check(test, "abc\n", 4, ESCAPE_NP | ESCAPE_OCTAL | ESCAPE_APPEND, "b",
	      "a\\142c\\012");
	check(test, "abc", 3, ESCAPE_NA | ESCAPE_HEX | ESCAPE_APPEND, "ac",
	      "\\x61b\\x63");
	check(test, "abc\x01", 4, ESCAPE_NAP | ESCAPE_HEX | ESCAPE_APPEND, "c",
	      "ab\\x63\\x01");
	check(test, "abc", 3, ESCAPE_NP | ESCAPE_OCTAL | ESCAPE_APPEND, NULL,
	      "abc");
}

static void test_empty_input(struct kunit *test)
{
	char buf[4];

	memset(buf, SENT, sizeof(buf));
	KUNIT_EXPECT_EQ(test, string_escape_mem("", 0, buf, sizeof(buf),
						ESCAPE_ANY, NULL), 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)buf[0], (unsigned char)SENT);
	KUNIT_EXPECT_EQ(test, string_escape_mem("abc", 0, NULL, 0, ESCAPE_ANY,
						NULL), 0);
}

static void test_isz_limits(struct kunit *test)
{
