	check(test, "abc", 2, ESCAPE_OCTAL, "a", "\\141b");
	check(test, "\n\n\n", 1, ESCAPE_SPACE, NULL, "\\n");
	check(test, "\n\n\n", 3, ESCAPE_SPACE, NULL, "\\n\\n\\n");
}

static void test_noflags(struct kunit *test)
