}

static void test_size_query(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, string_escape_mem("\n\1", 2, NULL, 0, ESCAPE_ANY, NULL), 2 + 4);
	KUNIT_EXPECT_EQ(test, string_escape_mem("\xff", 1, NULL, 0, ESCAPE_HEX, NULL), 4);
	KUNIT_EXPECT_EQ(test, string_escape_mem("\xff", 1, NULL, 0, ESCAPE_OCTAL, NULL), 4);
	KUNIT_EXPECT_EQ(test, string_escape_mem("\0", 1, NULL, 0, ESCAPE_NULL, NULL), 2);
	KUNIT_EXPECT_EQ(test, string_escape_mem("a", 1, NULL, 0, ESCAPE_NULL, NULL), 1);
	KUNIT_EXPECT_EQ(test, string_escape_mem("a\n\0", 3, NULL, 0, 0, NULL), 3);
}

static void test_trunc_two(struct kunit *test)
{
	check_trunc(test, "a\nb", 3, ESCAPE_SPACE, NULL, "a\\nb");
	check_trunc(test, "\"\a", 2, ESCAPE_SPECIAL, NULL, "\\\"\\a");
	check_trunc(test, "\0x", 2, ESCAPE_NULL, NULL, "\\0x");
}

static void test_trunc_four(struct kunit *test)
{
	check_trunc(test, "a\xff" "b", 3, ESCAPE_OCTAL, NULL, "\\141\\377\\142");
	check_trunc(test, "a\xab", 2, ESCAPE_HEX | ESCAPE_NA, NULL, "a\\xab");
	check_trunc(test, "\x01\x02", 2, ESCAPE_HEX, NULL, "\\x01\\x02");
}

static void test_trunc_passthrough(struct kunit *test)
{
	check_trunc(test, "abcd", 4, 0, NULL, "abcd");
	check_trunc(test, "abcd", 4, ESCAPE_NP, "bc", "abcd");
}

static void test_all_bytes_octal(struct kunit *test)
{
	char src[256], out[256 * 4 + 1];
	int i, ret;

	for (i = 0; i < 256; i++)
		src[i] = i;
	ret = string_escape_mem(src, 256, out, sizeof(out), ESCAPE_OCTAL, NULL);
	KUNIT_ASSERT_EQ(test, ret, 1024);
	for (i = 0; i < 256; i++) {
		KUNIT_EXPECT_EQ(test, out[i * 4], '\\');
		KUNIT_EXPECT_EQ(test, out[i * 4 + 1], '0' + ((i >> 6) & 7));
		KUNIT_EXPECT_EQ(test, out[i * 4 + 2], '0' + ((i >> 3) & 7));
		KUNIT_EXPECT_EQ(test, out[i * 4 + 3], '0' + (i & 7));
	}
}

static void test_all_bytes_hex(struct kunit *test)
{
	static const char hx[] = "0123456789abcdef";
	char src[256], out[256 * 4];
	int i, ret;

	for (i = 0; i < 256; i++)
		src[i] = i;
	ret = string_escape_mem(src, 256, out, sizeof(out), ESCAPE_HEX, NULL);
	KUNIT_ASSERT_EQ(test, ret, 1024);
	for (i = 0; i < 256; i++) {
		KUNIT_EXPECT_EQ(test, out[i * 4 + 1], 'x');
		KUNIT_EXPECT_EQ(test, out[i * 4 + 2], hx[i >> 4]);
		KUNIT_EXPECT_EQ(test, out[i * 4 + 3], hx[i & 15]);
	}
}

static void test_ascii_boundaries(struct kunit *test)
{
	check(test, "\x1f\x20\x7e\x7f", 4, ESCAPE_NP | ESCAPE_HEX, NULL,
	      "\\x1f \x7e\\x7f");
	check(test, "\x7f\x80", 2, ESCAPE_NA | ESCAPE_HEX, NULL, "\x7f\\x80");
	check(test, "\x7e\x7f\x80", 3, ESCAPE_NAP | ESCAPE_HEX, NULL,
	      "\x7e\\x7f\\x80");
}

