#include <kunit/test.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

/* Unescape @in with @flags and @size, check return value and output. */
static void check(struct kunit *test, const char *in, size_t size,
		  unsigned int flags, const char *exp, size_t exp_len)
{
	char src[64], dst[64];
	int ret;

	memset(dst, 0x55, sizeof(dst));
	strscpy(src, in, sizeof(src));
	ret = string_unescape(src, dst, size, flags);
	KUNIT_EXPECT_EQ(test, ret, (int)exp_len);
	KUNIT_EXPECT_EQ(test, (int)strlen(dst), (int)exp_len);
	KUNIT_EXPECT_MEMEQ(test, dst, exp, exp_len + 1);
}

static void agent_empty_and_plain(struct kunit *test)
{
	check(test, "", 0, UNESCAPE_ANY, "", 0);
	check(test, "", 5, UNESCAPE_ANY, "", 0);
	check(test, "hello", 0, UNESCAPE_ANY, "hello", 5);
	check(test, "hello", 0, 0, "hello", 5);
}

static void agent_no_flags(struct kunit *test)
{
	check(test, "a\\nb", 0, 0, "a\\nb", 4);
	check(test, "\\101\\x41\\\\", 0, 0, "\\101\\x41\\\\", 10);
}

static void agent_space(struct kunit *test)
{
	check(test, "\\n", 0, UNESCAPE_SPACE, "\n", 1);
	check(test, "\\r", 0, UNESCAPE_SPACE, "\r", 1);
	check(test, "\\t", 0, UNESCAPE_SPACE, "\t", 1);
	check(test, "\\v", 0, UNESCAPE_SPACE, "\v", 1);
	check(test, "\\f", 0, UNESCAPE_SPACE, "\f", 1);
	check(test, "a\\tb\\nc", 0, UNESCAPE_SPACE, "a\tb\nc", 5);
	/* not a space escape */
	check(test, "\\a", 0, UNESCAPE_SPACE, "\\a", 2);
	check(test, "\\N", 0, UNESCAPE_SPACE, "\\N", 2);
}

static void agent_octal(struct kunit *test)
{
	check(test, "\\1", 0, UNESCAPE_OCTAL, "\001", 1);
	check(test, "\\7", 0, UNESCAPE_OCTAL, "\007", 1);
	check(test, "\\12", 0, UNESCAPE_OCTAL, "\n", 1);
	check(test, "\\101", 0, UNESCAPE_OCTAL, "A", 1);
	check(test, "\\141", 0, UNESCAPE_OCTAL, "a", 1);
	check(test, "\\1015", 0, UNESCAPE_OCTAL, "A5", 2);
	check(test, "\\18", 0, UNESCAPE_OCTAL, "\0018", 2);
	check(test, "\\8", 0, UNESCAPE_OCTAL, "\\8", 2);
	check(test, "\\a", 0, UNESCAPE_OCTAL, "\\a", 2);
	check(test, "\\1\\2", 0, UNESCAPE_OCTAL, "\001\002", 2);
}

static void agent_hex(struct kunit *test)
{
	check(test, "\\x41", 0, UNESCAPE_HEX, "A", 1);
	check(test, "\\x4", 0, UNESCAPE_HEX, "\004", 1);
	check(test, "\\x0a", 0, UNESCAPE_HEX, "\n", 1);
	check(test, "\\xaF", 0, UNESCAPE_HEX, "\xaf", 1);
	check(test, "\\xFf", 0, UNESCAPE_HEX, "\xff", 1);
	check(test, "\\x414", 0, UNESCAPE_HEX, "A4", 2);
	check(test, "\\x4g", 0, UNESCAPE_HEX, "\004g", 2);
	check(test, "\\xg", 0, UNESCAPE_HEX, "\\xg", 3);
	check(test, "\\x", 0, UNESCAPE_HEX, "\\x", 2);
	check(test, "\\X41", 0, UNESCAPE_HEX, "\\X41", 4);
	check(test, "\\x/0", 0, UNESCAPE_HEX, "\\x/0", 4);
	check(test, "\\x:0", 0, UNESCAPE_HEX, "\\x:0", 4);
	check(test, "\\x@0", 0, UNESCAPE_HEX, "\\x@0", 4);
	check(test, "\\x`0", 0, UNESCAPE_HEX, "\\x`0", 4);
	check(test, "\\x9a", 0, UNESCAPE_HEX, "\x9a", 1);
	check(test, "\\xAg", 0, UNESCAPE_HEX, "\x0a" "g", 2);
}

static void agent_special(struct kunit *test)
{
	check(test, "\\\"", 0, UNESCAPE_SPECIAL, "\"", 1);
	check(test, "\\\\", 0, UNESCAPE_SPECIAL, "\\", 1);
	check(test, "\\a", 0, UNESCAPE_SPECIAL, "\a", 1);
	check(test, "\\e", 0, UNESCAPE_SPECIAL, "\e", 1);
	check(test, "\\n", 0, UNESCAPE_SPECIAL, "\\n", 2);
	check(test, "\\'", 0, UNESCAPE_SPECIAL, "\\'", 2);
	check(test, "\\\\n", 0, UNESCAPE_SPECIAL, "\\n", 2);
}

static void agent_any(struct kunit *test)
{
	check(test, "a\\n\\x41\\101\\\\\\\"\\a\\eZ", 0, UNESCAPE_ANY,
	      "a\nAA\\\"\a\eZ", 9);
	check(test, "\\q", 0, UNESCAPE_ANY, "\\q", 2);
}

static void agent_octal_quirks(struct kunit *test)
{
	/* num >= 32 stops further digits */
	check(test, "\\400", 0, UNESCAPE_OCTAL, " 0", 2);
	check(test, "\\377", 0, UNESCAPE_OCTAL, "\xff", 1);
	check(test, "\\777", 0, UNESCAPE_OCTAL, "?7", 2);
	check(test, "\\3770", 0, UNESCAPE_OCTAL, "\xff" "0", 2);
}

static void agent_trailing_backslash(struct kunit *test)
{
	check(test, "\\", 0, UNESCAPE_ANY, "\\", 1);
	check(test, "ab\\", 0, UNESCAPE_ANY, "ab\\", 3);
	check(test, "\\\\\\", 0, UNESCAPE_ANY, "\\\\", 2);
}

static void agent_size_limit(struct kunit *test)
{
	check(test, "abcdef", 1, 0, "", 0);
	check(test, "abcdef", 2, 0, "a", 1);
	check(test, "abcdef", 3, 0, "ab", 2);
	check(test, "abcdef", 6, 0, "abcde", 5);
	check(test, "abcdef", 7, 0, "abcdef", 6);
	check(test, "abcdef", 8, 0, "abcdef", 6);
	check(test, "abcdef", 100, 0, "abcdef", 6);
}

static void agent_size_with_escape(struct kunit *test)
{
	check(test, "\\nX", 1, UNESCAPE_ANY, "", 0);
	/* not enough room for an escape: backslash copied literally */
	check(test, "\\nX", 2, UNESCAPE_ANY, "\\", 1);
	check(test, "\\nX", 3, UNESCAPE_ANY, "\n", 1);
	check(test, "\\nX", 4, UNESCAPE_ANY, "\nX", 2);
	check(test, "\\nX", 5, UNESCAPE_ANY, "\nX", 2);
	check(test, "a\\nb", 3, UNESCAPE_ANY, "a\\", 2);
	check(test, "a\\nb", 4, UNESCAPE_ANY, "a\n", 2);
	check(test, "a\\nb", 5, UNESCAPE_ANY, "a\nb", 3);
}

static void agent_in_place(struct kunit *test)
{
	char buf[] = "a\\tb\\x41\\101\\\\";
	int ret = string_unescape(buf, buf, 0, UNESCAPE_ANY);

	KUNIT_EXPECT_EQ(test, ret, 6);
	KUNIT_EXPECT_STREQ(test, buf, "a\tbAA\\");
}

