/* Parse s with room for n ints; check count, end offset and parsed values. */
static void check(struct kunit *t, const char *s, int n, int cnt, int off,
		  const int *exp, int nexp)
{
	int a[16];
	char *r;
	int k;

	memset(a, 0x55, sizeof(a));
	r = get_options(s, n, a);
	KUNIT_EXPECT_EQ(t, a[0], cnt);
	KUNIT_EXPECT_EQ(t, (int)(r - s), off);
	for (k = 0; k < nexp; k++)
		KUNIT_EXPECT_EQ(t, a[k + 1], exp[k]);
}

#define CHK(t, s, n, cnt, off, ...)					\
do {									\
	static const int e_[] = { 0, ##__VA_ARGS__ };			\
	check(t, s, n, cnt, off, e_ + 1, ARRAY_SIZE(e_) - 1);		\
} while (0)

static void t_single(struct kunit *t)
{
	CHK(t, "42", 8, 1, 2, 42);
}

