/*
 * lib/agent_kunit.c: KUnit tests for __hsiphash_aligned().
 */
#include <kunit/test.h>
#include <linux/siphash.h>
#include <linux/bitops.h>
#include <linux/string.h>
#include <linux/slab.h>

#if BITS_PER_LONG == 64 && !defined(CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS)

#define MAXLEN 40

static const hsiphash_key_t key0 = { { 0x0706050403020100UL, 0x0f0e0d0c0b0a0908UL } };

#define RND(v0, v1, v2, v3) do { \
	v0 += v1; v1 = rol64(v1, 13); v1 ^= v0; v0 = rol64(v0, 32); \
	v2 += v3; v3 = rol64(v3, 16); v3 ^= v2; \
	v0 += v3; v3 = rol64(v3, 21); v3 ^= v0; \
	v2 += v1; v1 = rol64(v1, 17); v1 ^= v2; v2 = rol64(v2, 32); \
} while (0)

/* Independent byte-wise SipHash-1-3 reference, folded to 32 bits. */
static u32 ref_hash(const u8 *d, size_t len, const hsiphash_key_t *k)
{
	u64 v0 = 0x736f6d6570736575ULL ^ k->key[0];
	u64 v1 = 0x646f72616e646f6dULL ^ k->key[1];
	u64 v2 = 0x6c7967656e657261ULL ^ k->key[0];
	u64 v3 = 0x7465646279746573ULL ^ k->key[1];
	u64 b = (u64)len << 56;
	size_t i, full = len / 8;
	int j;

	for (i = 0; i < full; i++) {
		u64 m = 0;

		for (j = 7; j >= 0; j--)
			m = (m << 8) | d[i * 8 + j];
		v3 ^= m;
		RND(v0, v1, v2, v3);
		v0 ^= m;
	}
	for (j = 0; j < (int)(len % 8); j++)
		b |= (u64)d[full * 8 + j] << (8 * j);
	v3 ^= b;
	RND(v0, v1, v2, v3);
	v0 ^= b;
	v2 ^= 0xff;
	RND(v0, v1, v2, v3);
	RND(v0, v1, v2, v3);
	RND(v0, v1, v2, v3);
	return (u32)((v0 ^ v1) ^ (v2 ^ v3));
}

static void fill(u8 *p, size_t n)
{
	size_t i;

	for (i = 0; i < n; i++)
		p[i] = (u8)(i * 7 + 1);
}

static void test_all_lengths(struct kunit *test)
{
	u8 buf[MAXLEN] __aligned(8);
	size_t len;

	fill(buf, sizeof(buf));
	for (len = 0; len <= MAXLEN; len++)
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(buf, len, &key0),
				    ref_hash(buf, len, &key0), "len=%zu", len);
}

static void test_empty(struct kunit *test)
{
	u8 buf[8] __aligned(8) = { 0 };

	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(buf, 0, &key0),
			ref_hash(buf, 0, &key0));
}

static void test_tail_each_byte(struct kunit *test)
{
	u8 buf[MAXLEN] __aligned(8);
	size_t len, pos;

	/* flipping any single byte must change the hash and match ref */
	for (len = 1; len <= 17; len++) {
		u32 base;

		fill(buf, sizeof(buf));
		base = __hsiphash_aligned(buf, len, &key0);
		for (pos = 0; pos < len; pos++) {
			u32 h;

			buf[pos] ^= 0x80;
			h = __hsiphash_aligned(buf, len, &key0);
			KUNIT_EXPECT_EQ_MSG(test, h, ref_hash(buf, len, &key0),
					    "len=%zu pos=%zu", len, pos);
			KUNIT_EXPECT_NE_MSG(test, h, base,
					    "len=%zu pos=%zu", len, pos);
			buf[pos] ^= 0x80;
		}
	}
}

static void test_bytes_past_len_ignored(struct kunit *test)
{
	u8 a[MAXLEN] __aligned(8), b[MAXLEN] __aligned(8);
	size_t len;

	for (len = 0; len < 24; len++) {
		fill(a, sizeof(a));
		memset(b, 0xa5, sizeof(b));
		memcpy(b, a, len);
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(a, len, &key0),
				    __hsiphash_aligned(b, len, &key0),
				    "len=%zu", len);
	}
}

static void test_length_matters(struct kunit *test)
{
	u8 buf[MAXLEN] __aligned(8) = { 0 };
	size_t len;

	/* zero-filled buffers of different lengths must hash differently */
	for (len = 0; len < 24; len++)
		KUNIT_EXPECT_NE_MSG(test, __hsiphash_aligned(buf, len, &key0),
				    __hsiphash_aligned(buf, len + 1, &key0),
				    "len=%zu", len);
}

static void test_key_sensitivity(struct kunit *test)
{
	u8 buf[MAXLEN] __aligned(8);
	hsiphash_key_t k1 = key0, k2 = key0;
	size_t len;

	fill(buf, sizeof(buf));
	k1.key[0] ^= 1;
	k2.key[1] ^= 1UL << 63;
	for (len = 0; len <= 17; len++) {
		u32 h = __hsiphash_aligned(buf, len, &key0);

		KUNIT_EXPECT_NE(test, h, __hsiphash_aligned(buf, len, &k1));
		KUNIT_EXPECT_NE(test, h, __hsiphash_aligned(buf, len, &k2));
		KUNIT_EXPECT_EQ(test, __hsiphash_aligned(buf, len, &k1),
				ref_hash(buf, len, &k1));
		KUNIT_EXPECT_EQ(test, __hsiphash_aligned(buf, len, &k2),
				ref_hash(buf, len, &k2));
	}
}

static void test_zero_key_and_ff_data(struct kunit *test)
{
	hsiphash_key_t zk = { { 0, 0 } };
	hsiphash_key_t fk = { { ~0UL, ~0UL } };
	u8 buf[MAXLEN] __aligned(8);
	size_t len;

	memset(buf, 0xff, sizeof(buf));
	for (len = 0; len <= MAXLEN; len++) {
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(buf, len, &zk),
				    ref_hash(buf, len, &zk), "len=%zu", len);
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(buf, len, &fk),
				    ref_hash(buf, len, &fk), "len=%zu", len);
	}
}

static void test_offsets_aligned(struct kunit *test)
{
	u8 buf[MAXLEN + 16] __aligned(8);
	size_t off, len;

	fill(buf, sizeof(buf));
	for (off = 0; off <= 16; off += 8)
		for (len = 0; len <= MAXLEN; len++)
			KUNIT_EXPECT_EQ_MSG(test,
				__hsiphash_aligned(buf + off, len, &key0),
				ref_hash(buf + off, len, &key0),
				"off=%zu len=%zu", off, len);
}

static void test_exact_heap_buffer(struct kunit *test)
{
	size_t len;

	/* hash exactly-sized allocations */
	for (len = 1; len <= 20; len++) {
		u8 *p = kunit_kmalloc(test, len, GFP_KERNEL);

		KUNIT_ASSERT_NOT_NULL(test, p);
		fill(p, len);
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(p, len, &key0),
				    ref_hash(p, len, &key0), "len=%zu", len);
	}
}

static void test_matches_unaligned(struct kunit *test)
{
	u8 buf[MAXLEN] __aligned(8);
	size_t len;

	fill(buf, sizeof(buf));
	for (len = 0; len <= MAXLEN; len++)
		KUNIT_EXPECT_EQ(test, __hsiphash_aligned(buf, len, &key0),
				__hsiphash_unaligned(buf, len, &key0));
}

static void test_deterministic_and_const(struct kunit *test)
{
	u8 buf[16] __aligned(8), copy[16];

	fill(buf, sizeof(buf));
	memcpy(copy, buf, sizeof(buf));
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(buf, 16, &key0),
			__hsiphash_aligned(buf, 16, &key0));
	KUNIT_EXPECT_MEMEQ(test, buf, copy, sizeof(buf));
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(test_all_lengths),
	KUNIT_CASE(test_empty),
	KUNIT_CASE(test_tail_each_byte),
	KUNIT_CASE(test_bytes_past_len_ignored),
	KUNIT_CASE(test_length_matters),
	KUNIT_CASE(test_key_sensitivity),
	KUNIT_CASE(test_zero_key_and_ff_data),
	KUNIT_CASE(test_offsets_aligned),
	KUNIT_CASE(test_exact_heap_buffer),
	KUNIT_CASE(test_matches_unaligned),
	KUNIT_CASE(test_deterministic_and_const),
	{}
};
