static void test_unavailable(struct kunit *test)
{
	kunit_skip(test, "__hsiphash_aligned not built or 32-bit variant");
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(test_unavailable),
	{}
};
